def make_share_summary(
    crop: str,
    action: str,
    price: float,
    mandi: str,
    trend_pct: float,
    primary_reason: str,
    language: str = "mr"
) -> Dict[str, str]:
    """
    Action Tool: Creates a concise, formatted, WhatsApp-ready text summary
    with emojis in all 12 regional languages.
    """
    lang = language if language in LOCALIZED_SHARE_TEMPLATES else "mr"
    t_head, t_crop, t_mandi, t_price, t_trend, t_action, t_reason, t_foot = LOCALIZED_SHARE_TEMPLATES[lang]
    
    localized_crop = get_localized_crop(crop, lang) or crop
    localized_mandi = get_localized_place(mandi, lang) or mandi
    action_text = ACTION_LABELS.get(action, {}).get(lang, action)

    text = (
        f"{t_head}\n"
        f"📌 *{t_crop}:* {localized_crop} | *{t_mandi}:* {localized_mandi}\n"
        f"💰 *{t_price}:* ₹{price:,.0f} (₹{price/100:.1f}/kg)\n"
        f"📈 *{t_trend}:* {trend_pct:+.1f}%\n"
        f"💡 *{t_action}:* *{action_text}*\n"
        f"🔍 *{t_reason}:* {primary_reason}\n\n"
        f"📲 _{t_foot}_"
    )

    return {
        "text": text,
        "whatsapp_url": f"https://api.whatsapp.com/send?text={text}"
    }
